1	export type QuoteResult = {
2	  premium: number;
3	};
4	
5	export type ClaimResult = {
6	  payout: number;
7	  remainingCap: number;
8	};
9	
10	export type StepResult = QuoteResult | ClaimResult;
11	
12	export type ScenarioResult = {
13	  results: StepResult[];
14	};
15	
16	const BASE_PREMIUMS = {
17	  sword: 100,
18	  amulet: 60,
19	  staff: 80,
20	  potion: 40,
21	  rune: 25,
22	  moonstone: 25,
23	} as const satisfies Record<string, number>;
24	
25	const INSURANCE_VALUES = {
26	  sword: 1000,
27	  amulet: 600,
28	  staff: 800,
29	  potion: 400,
30	  rune: 250,
31	  moonstone: 250,
32	} as const satisfies Record<keyof typeof BASE_PREMIUMS, number>;
33	
34	type InsurableItemType = keyof typeof BASE_PREMIUMS;
35	
36	type Item = {
37	  type: InsurableItemType;
38	  material?: string;
39	  enchantment?: number;
40	  cursed?: boolean;
41	};
42	
43	type QuoteStep = {
44	  op: "quote";
45	  items: Item[];
46	};
47	
48	type Damage = {
49	  itemType: string;
50	  amount: number;
51	};
52	
53	type Incident = {
54	  cause: string;
55	  damages: Damage[];
56	};
57	
58	type ClaimStep = {
59	  op: "claim";
60	  policy: number;
61	  incident: Incident;
62	};
63	
64	type Step = QuoteStep | ClaimStep;
65	
66	type Customer = {
67	  yearsWithMHPCO: number;
68	};
69	
70	type Scenario = {
71	  customer: Customer;
72	  steps: Step[];
73	};
74	
75	const PROCESSING_FEE = 5;
76	const INITIAL_ASSESSMENT_SURCHARGE_PERCENT = 10;
77	const CURSE_SURCHARGE_PERCENT = 50;
78	const HIGH_ENCHANTMENT_THRESHOLD = 5;
79	const HIGH_ENCHANTMENT_SURCHARGE_PERCENT = 30;
80	const LOYALTY_THRESHOLD_YEARS = 2;
81	const LOYALTY_DISCOUNT_PERCENT = 20;
82	const FOLLOW_UP_DISCOUNT_PERCENT = 15;
83	
84	const percentOf = (amount: number, percent: number): number =>
85	  (amount * percent) / 100;
86	
87	// The MHPCO always rounds in its own favour: premiums (which the customer
88	// pays) round up, payouts (which it pays out) round down.
89	const roundedUpInMHPCOsFavour = (premium: number): number => Math.ceil(premium);
90	
91	const itemBasePremiumOf = (item: Item): number => BASE_PREMIUMS[item.type];
92	
93	// Exactly this many components of the same type form a "building block",
94	// priced as a unit rather than per item.
95	const BUILDING_BLOCK_SIZE = 3;
96	const BUILDING_BLOCK_BASE_PREMIUM = 60;
97	
98	const sumOf = (amounts: number[]): number =>
99	  amounts.reduce((total, amount) => total + amount, 0);
100	
101	// The MHPCO insures exactly the item types its price list names.
102	const insurableItemTypes = Object.keys(BASE_PREMIUMS) as InsurableItemType[];
103	
104	const isInsurableItemType = (type: string): type is InsurableItemType =>
105	  insurableItemTypes.includes(type as InsurableItemType);
106	
107	const alikeItemGroups = (items: Item[]): Item[][] =>
108	  insurableItemTypes
109	    .map((type) => items.filter((item) => item.type === type))
110	    .filter((alikeItems) => alikeItems.length > 0);
111	
112	const formsBuildingBlock = (alikeItems: Item[]): boolean =>
113	  alikeItems.length === BUILDING_BLOCK_SIZE;
114	
115	const alikeGroupBasePremiumOf = (alikeItems: Item[]): number =>
116	  formsBuildingBlock(alikeItems)
117	    ? BUILDING_BLOCK_BASE_PREMIUM
118	    : sumOf(alikeItems.map(itemBasePremiumOf));
119	
120	const policyBasePremiumOf = (items: Item[]): number =>
121	  sumOf(alikeItemGroups(items).map(alikeGroupBasePremiumOf));
122	
123	const isCursed = (item: Item): boolean => item.cursed === true;
124	
125	// An item without an enchantment counts as enchantment 0 everywhere.
126	const enchantmentOf = (item: Item): number => item.enchantment ?? 0;
127	
128	const isHighlyEnchanted = (item: Item): boolean =>
129	  enchantmentOf(item) >= HIGH_ENCHANTMENT_THRESHOLD;
130	
131	// A modifier adjusts a base premium by a percentage of it, when it applies to
132	// the subject it is about (an item, a contract, ...). A surcharge has a
133	// positive percent, a discount a negative one, so they all combine by summing.
134	// Modifiers are cumulative: every applicable one applies.
135	type Modifier<Subject> = {
136	  appliesTo: (subject: Subject) => boolean;
137	  percent: number;
138	};
139	
140	const modifierTotalOf = <Subject>(
141	  modifiers: Modifier<Subject>[],
142	  subject: Subject,
143	  basePremium: number,
144	): number =>
145	  sumOf(
146	    modifiers
147	      .filter((modifier) => modifier.appliesTo(subject))
148	      .map((modifier) => percentOf(basePremium, modifier.percent)),
149	  );
150	
151	const ITEM_MODIFIERS: Modifier<Item>[] = [
152	  { appliesTo: isCursed, percent: CURSE_SURCHARGE_PERCENT },
153	  { appliesTo: isHighlyEnchanted, percent: HIGH_ENCHANTMENT_SURCHARGE_PERCENT },
154	];
155	
156	// Item-specific modifiers apply to the base premium of the affected item.
157	const itemModifierTotalOf = (item: Item): number =>
158	  modifierTotalOf(ITEM_MODIFIERS, item, itemBasePremiumOf(item));
159	
160	const isLongStanding = (customer: Customer): boolean =>
161	  customer.yearsWithMHPCO >= LOYALTY_THRESHOLD_YEARS;
162	
163	// A contract is one quote within a scenario. A quote is a follow-up when the
164	// customer already holds a policy with the MHPCO at the time it is drawn up.
165	type Contract = {
166	  customer: Customer;
167	  heldPoliciesBefore: number;
168	};
169	
170	const isFollowUpContract = (contract: Contract): boolean =>
171	  contract.heldPoliciesBefore > 0;
172	
173	// Policy-wide modifiers apply to the policy base premium and are about the
174	// contract as a whole rather than any single item.
175	const alwaysApplies = (): boolean => true;
176	
177	const POLICY_MODIFIERS: Modifier<Contract>[] = [
178	  { appliesTo: alwaysApplies, percent: INITIAL_ASSESSMENT_SURCHARGE_PERCENT },
179	  {
180	    appliesTo: (contract) => isLongStanding(contract.customer),
181	    percent: -LOYALTY_DISCOUNT_PERCENT,
182	  },
183	  { appliesTo: isFollowUpContract, percent: -FOLLOW_UP_DISCOUNT_PERCENT },
184	];
185	
186	const policyModifierTotalOf = (
187	  contract: Contract,
188	  policyBasePremium: number,
189	): number => modifierTotalOf(POLICY_MODIFIERS, contract, policyBasePremium);
190	
191	const quote = (step: QuoteStep, contract: Contract): QuoteResult => {
192	  const policyBasePremium = policyBasePremiumOf(step.items);
193	  const itemModifiers = sumOf(step.items.map(itemModifierTotalOf));
194	  const policyModifiers = policyModifierTotalOf(contract, policyBasePremium);
195	
196	  return {
197	    premium: roundedUpInMHPCOsFavour(
198	      policyBasePremium + itemModifiers + policyModifiers + PROCESSING_FEE,
199	    ),
200	  };
201	};
202	
203	const DEDUCTIBLE_PER_DAMAGE = 100;
204	const CAP_MULTIPLIER = 2;
205	const PARTIAL_REIMBURSEMENT_ENCHANTMENT_THRESHOLD = 8;
206	const PARTIAL_REIMBURSEMENT_PERCENT = 50;
207	
208	const roundedDownInMHPCOsFavour = (payout: number): number =>
209	  Math.floor(payout);
210	
211	const insuranceValueOf = (item: Item): number => INSURANCE_VALUES[item.type];
212	
213	// A policy is created by a quote step and remembers how much of its cap the
214	// customer has already claimed.
215	type Policy = {
216	  items: Item[];
217	  remainingCap: number;
218	};
219	
220	const isReimbursedInPart = (item: Item): boolean =>
221	  enchantmentOf(item) >= PARTIAL_REIMBURSEMENT_ENCHANTMENT_THRESHOLD;
222	
223	// The reimbursement clauses decide how much of the damage is covered; the
224	// deductible is then withheld from that amount.
225	const reimbursementOf = (damage: Damage, item: Item): number =>
226	  isReimbursedInPart(item)
227	    ? percentOf(damage.amount, PARTIAL_REIMBURSEMENT_PERCENT)
228	    : damage.amount;
229	
230	const damagePayoutOf = (damage: Damage, item: Item): number =>
231	  reimbursementOf(damage, item) - DEDUCTIBLE_PER_DAMAGE;
232	
233	// The insured item a damage entry is about. The MHPCO does not pay for what it
234	// did not insure, so a damage naming anything else is rejected outright.
235	const damagedItemIn = (policy: Policy, damage: Damage): Item => {
236	  const item = policy.items.find((item) => item.type === damage.itemType);
237	
238	  if (item === undefined) {
239	    throw new Error(`damaged item is not insured by this policy: ${damage.itemType}`);
240	  }
241	
242	  return item;
243	};
244	
245	const incidentPayoutOf = (incident: Incident, policy: Policy): number =>
246	  roundedDownInMHPCOsFavour(
247	    sumOf(
248	      incident.damages.map((damage) =>
249	        damagePayoutOf(damage, damagedItemIn(policy, damage)),
250	      ),
251	    ),
252	  );
253	
254	// The total payout per policy is capped, so a claim can only draw what the cap
255	// still holds.
256	const drawnFromCap = (desiredPayout: number, policy: Policy): number =>
257	  Math.min(desiredPayout, policy.remainingCap);
258	
259	// Claiming draws the payout from the policy's remaining cap, so it yields both
260	// the result and the policy as it stands afterwards, rather than mutating.
261	const claim = (
262	  step: ClaimStep,
263	  policy: Policy,
264	): { result: ClaimResult; policy: Policy } => {
265	  const payout = drawnFromCap(incidentPayoutOf(step.incident, policy), policy);
266	  const remainingCap = policy.remainingCap - payout;
267	
268	  return {
269	    result: { payout, remainingCap },
270	    policy: { ...policy, remainingCap },
271	  };
272	};
273	
274	const policyFor = (items: Item[]): Policy => ({
275	  items,
276	  remainingCap: CAP_MULTIPLIER * sumOf(items.map(insuranceValueOf)),
277	});
278	
279	// A scenario is processed step by step: each step produces a result and may
280	// leave behind policies the later steps claim against. Policies are keyed by
281	// the index of the quote step that created them, which is how claim steps
282	// refer to them.
283	type Office = {
284	  policies: Map<number, Policy>;
285	  results: StepResult[];
286	};
287	
288	const emptyOffice = (): Office => ({ policies: new Map(), results: [] });
289	
290	// The scenario arrives as untyped JSON, so the item types it names have to be
291	// checked against the MHPCO's price list before anything is priced.
292	const assertItemTypeIsInsurable = (item: Item): void => {
293	  if (!isInsurableItemType(item.type)) {
294	    throw new Error(`unknown item type: ${item.type}`);
295	  }
296	};
297	
298	// Every step yields its result plus the policy it wrote, under the key that
299	// later steps use to find it.
300	type StepOutcome = {
301	  result: StepResult;
302	  policyKey: number;
303	  policy: Policy;
304	};
305	
306	const withOutcomeRecorded = (office: Office, outcome: StepOutcome): Office => ({
307	  policies: new Map(office.policies).set(outcome.policyKey, outcome.policy),
308	  results: [...office.results, outcome.result],
309	});
310	
311	const outcomeOf = (
312	  office: Office,
313	  step: Step,
314	  stepIndex: number,
315	  customer: Customer,
316	): StepOutcome => {
317	  if (step.op === "quote") {
318	    step.items.forEach(assertItemTypeIsInsurable);
319	    // Claims re-file the policy they draw on under its existing key, so the
320	    // number of policies on file only ever grows on a quote.
321	    const contract = { customer, heldPoliciesBefore: office.policies.size };
322	
323	    return {
324	      result: quote(step, contract),
325	      policyKey: stepIndex,
326	      policy: policyFor(step.items),
327	    };
328	  }
329	
330	  const claimed = claim(step, office.policies.get(step.policy)!);
331	
332	  return {
333	    result: claimed.result,
334	    policyKey: step.policy,
335	    policy: claimed.policy,
336	  };
337	};
338	
339	export const runScenario = (scenario: Scenario): ScenarioResult => {
340	  const office = scenario.steps.reduce(
341	    (office, step, stepIndex) =>
342	      withOutcomeRecorded(
343	        office,
344	        outcomeOf(office, step, stepIndex, scenario.customer),
345	      ),
346	    emptyOffice(),
347	  );
348	
349	  return { results: office.results };
350	};
