// The insured item a damage entry is about. The MHPCO does not pay for what it
// did not insure, so a damage naming anything else is rejected outright.
const damagedItemIn = (policy: Policy, damage: Damage): Item => {
  const item = policy.items.find((item) => item.type === damage.itemType);

  if (item === undefined) {
    throw new Error(`damaged item is not insured by this policy: ${damage.itemType}`);
  }

  return item;
};

